import React from "react";
import ReactDOM from "react-dom/client";

function App() {
  return (
    <div
      style={{
        minHeight: "100vh",
        backgroundColor: "#0b1f33",
        color: "white",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "Arial, sans-serif",
        textAlign: "center",
      }}
    >
      <h1 style={{ fontSize: "48px" }}>
        🌊 Marine Intelligence Platform
      </h1>

      <p style={{ fontSize: "20px", color: "#8fd3ff" }}>
        Frontend is running successfully!
      </p>

      <button
        style={{
          marginTop: "20px",
          padding: "14px 30px",
          fontSize: "16px",
          border: "none",
          borderRadius: "8px",
          cursor: "pointer",
        }}
      >
        Get Started
      </button>
    </div>
  );
}

const root = ReactDOM.createRoot(
  document.getElementById("root")
);

root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);
